import{_ as i,o,c as a,a1 as n}from"./chunks/framework.DP1PKHY4.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"4-GUIDES/configuration.md","lastUpdated":1786753303000}'),d={name:"guide/configuration.md"};function c(l,e,t,s,r,E){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><h2 id="config-file" tabindex="-1">Config File <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config File&quot;">​</a></h2><p><code>~/.config/neotrix/config.toml</code></p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;opencode&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enc:...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 加密存储 (AES-256-GCM), 见下文</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;opencode/gpt-4o-mini&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color_mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span></span></code></pre></div><h2 id="api-key-加密存储" tabindex="-1">API Key 加密存储 <a class="header-anchor" href="#api-key-加密存储" aria-label="Permalink to &quot;API Key 加密存储&quot;">​</a></h2><p>API 密钥不落明文。<code>neotrix config encrypt-keys</code> 会加密所有明文 <code>api_key</code>/<code>secret</code> 字段， <code>decrypt-keys</code> 用于解密（谨慎使用）。加密值以 <code>enc:</code> 前缀存储。</p><p>密钥来源优先级 (见 <code>nt_shield/key_encryption.rs</code>):</p><ol><li><strong>OS keychain</strong> (macOS Keychain / libsecret), 生产默认</li><li><code>NEOTRIX_VAULT_KEY</code> 环境变量 — 显式提供 32 字节密钥</li><li>机器派生密钥 — <strong>仅显式 opt-in</strong>: <code>NEOTRIX_ALLOW_MACHINE_KEY=1</code></li></ol><h3 id="解密失败处理" tabindex="-1">解密失败处理 <a class="header-anchor" href="#解密失败处理" aria-label="Permalink to &quot;解密失败处理&quot;">​</a></h3><p>启动时若无法用当前密钥解密旧加密值, 会打印警告 <code>[config] warning: failed to decrypt api_key</code> 并<strong>降级继续运行</strong> (不阻断启动)。常见原因: keychain 条目失效/重装系统。 修复: 重新 <code>neotrix config encrypt-keys</code> (用新密钥重加密), 或设置 <code>NEOTRIX_VAULT_KEY</code> 提供确定性的密钥。</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>Variables prefixed <code>NEOTRIX_</code>:</p><ul><li><code>NEOTRIX_PROVIDER</code> — LLM provider</li><li><code>NEOTRIX_API_KEY</code> — API key (优先于 config.toml)</li><li><code>NEOTRIX_BASE_URL</code> — LLM base URL (自定义端点)</li><li><code>NEOTRIX_MODEL</code> — LLM model</li><li><code>NEOTRIX_EMBEDDING_API_KEY</code> — Embedding API key (语义搜索)</li><li><code>NEOTRIX_EMBEDDING_BASE_URL</code> — Embedding base URL</li><li><code>NEOTRIX_EMBEDDING_MODEL</code> — Embedding model</li><li><code>NEOTRIX_EMBEDDING_DIMENSION</code> — Embedding dimension</li><li><code>NEOTRIX_API_TOKEN</code> — HTTP serve 模式 Bearer 认证 token (保护 <code>/api/*</code>)</li><li><code>NEOTRIX_VAULT_KEY</code> — 32 字节 AES 密钥 (替代 OS keychain)</li><li><code>NEOTRIX_ALLOW_MACHINE_KEY</code> — 显式允许机器派生密钥 (默认拒绝, C-3 加固)</li><li><code>NEOTRIX_NETWORK_UNBLOCK</code> — 设为 <code>1</code> 放开 LLM 网络访问 (默认沙箱隔离拦截外部调用)</li><li><code>NEOTRIX_COT_*</code> — CoT 推理参数 (MODEL/MAX_TOKENS/TEMPERATURE/THINKING_BUDGET/STRUCTURED)</li><li><code>NEOTRIX_DISPATCH_*</code> — 多 agent 调度参数 (CONCURRENCY/AGGRESSION/TIMEOUT/MAX_SUBTASKS/VERIFIER/COT/HIDE_INTERNAL)</li><li><code>NEOTRIX_CLOUD_ENDPOINT</code> — 云同步端点</li><li><code>NEOTRIX_DISCOVER_LOCAL</code> / <code>NEOTRIX_DISCOVER_PROBE</code> — 本地服务发现</li><li><code>NEOTRIX_QUIET</code> — 抑制启动配置打印</li></ul>`,13)])])}const h=i(d,[["render",c]]);export{p as __pageData,h as default};
